"""분리한 PNG를 내장한 오프라인 검토 페이지를 만든다."""
from pathlib import Path
import base64
import json
import hashlib

ROOT = Path(__file__).resolve().parents[4]
BASE = ROOT / 'Docs/References/codex_k019_v1'
def data(path):
    return 'data:image/png;base64,' + base64.b64encode(path.read_bytes()).decode()

assets = {p.stem: data(p) for p in sorted((BASE/'png').glob('*.png'))}
assets['hero'] = data(ROOT/'Game/Assets/_Project/Art/Characters/Hero/hero_back_idle.png')
page = r'''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>K-019 명령 메뉴 그림 1판</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#101613;color:#eee4cf;font:15px/1.6 'Malgun Gothic',sans-serif}main{max-width:1200px;margin:auto;padding:36px 64px}h1{font:32px Batang,serif;margin:8px 0}h2{font-size:20px;margin-top:32px}.tag{color:#d5b16b;letter-spacing:2px;font-size:12px}p{color:#b5bcae}button,select,input{font:inherit}button,select{color:#eee4cf;background:#26352d;border:1px solid #8b7449;padding:8px 14px;border-radius:3px}button{cursor:pointer}button:focus-visible{outline:2px solid #eee4cf}.tools{display:flex;gap:16px;flex-wrap:wrap;align-items:center;margin:22px 0}.scene{height:590px;position:relative;overflow:auto;background:radial-gradient(ellipse at 30% 20%,#4d5d52,#26332a 60%,#131c18);border:1px solid #526050}.scene.light{background:#a5aaa0}.scene.night{background:#080d13}.scene:after{content:'배치 목업 · 실제 게임 캡처 아님';position:absolute;left:16px;bottom:12px;color:#d5b16b;font-size:12px}.hero{position:absolute;left:55px;top:185px;width:154px;height:231px;image-rendering:pixelated}.rail{position:absolute;left:214px;top:115px;width:3px;height:358px;image-rendering:pixelated}.menu{position:absolute;left:240px;top:125px;width:620px;height:370px}.choice{position:absolute;left:0;width:380px;height:48px;border:0;background:none;padding:0;transform-origin:left center;transform:rotate(-6deg);transition:transform .12s;isolation:isolate;text-align:left}.choice .band{position:absolute;inset:0;border-style:solid;border-width:8px 64px;border-image-slice:8 64 fill;border-image-width:8px 64px;border-image-repeat:stretch;z-index:-1}.choice .badge{position:absolute;left:8px;top:7px;width:34px;height:34px;image-rendering:pixelated}.choice .label{position:absolute;left:52px;top:5px;font-size:24px;white-space:nowrap;text-shadow:1px 1px 2px #000,-1px -1px #000}.choice .under{position:absolute;left:48px;bottom:2px;width:300px;height:8px;image-rendering:pixelated}.choice.active{transform:rotate(-6deg) scale(1.45);z-index:10}.scene.three .menu{top:210px}.scene.three .rail{top:195px;height:210px}.status{color:#d5b16b;min-height:24px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:12px}.tile{padding:18px;background:#1d2821;border:1px solid #405044;overflow:auto}.check{background:repeating-conic-gradient(#475148 0 25%,#333d35 0 50%) 0/16px 16px;padding:12px;min-height:75px}.tile img{image-rendering:pixelated;max-width:100%}.tile code{font-size:12px;color:#b6c4b8}.slice{height:80px;max-width:none;border-style:solid;border-width:8px 64px;border-image-slice:8 64 fill;border-image-width:8px 64px}.note{padding:14px 18px;border-left:3px solid #d5b16b;background:#1d2821}table{border-collapse:collapse;width:100%}td,th{border-bottom:1px solid #405044;padding:10px;text-align:left}footer{margin:32px 0;color:#9aa999}@media(max-width:700px){main{padding:20px 12px}.scene{height:590px}.hero{left:5px}.rail{left:145px}.menu{left:170px}}
</style><main><div class="tag">HUMAN LAST RAMPART · K-019 · 1판</div><h1>주인공 옆으로 펼치는 명령</h1><p>어두운 붓 띠와 황동색 흔적. 사용자 방향 확정 전 시안입니다.</p>
<div class="tools"><label>구성 <select id="mode"><option value="six">명령 6개</option><option value="three">처음 메뉴 3개</option></select></label><label>배경 <select id="bg"><option value="">들판색</option><option value="light">밝은 안개색</option><option value="night">밤색</option></select></label><button id="reset">선택 해제</button><span>마우스·초점·숫자 1~6으로 비교</span></div>
<div class="scene" id="scene"><img class="hero" id="hero" alt="기존 주인공 뒷모습 참고"><img class="rail" id="rail" alt="양끝이 흐려지는 세로선"><div class="menu" id="menu"></div></div><div class="status" id="status" aria-live="polite">가까운 항목을 1.45배로 확대합니다.</div>
<h2>분리한 그림</h2><div class="grid" id="assets"></div>
<h2>9칸 늘이기 확인</h2><p>원본은 수평 380×48px. 좌우 64px, 위아래 8px을 보존합니다. 아래는 같은 그림을 280·380·520px로 늘린 모습입니다.</p><div id="slices" class="grid"></div>
<h2>연결할 때의 규격안</h2><table><tr><th>부품</th><th>크기</th><th>사용</th></tr><tr><td>보통 / 마우스 올림 띠</td><td>380×48</td><td>9칸 늘이기 후 부모를 위로 6° 회전</td></tr><tr><td>금색 밑줄</td><td>320×8</td><td>별도 레이어, 끝 모양 보존 권장</td></tr><tr><td>번호 표식</td><td>34×34, 1~6 및 빈 표식</td><td>번호를 띠와 별도로 배치</td></tr><tr><td>주인공 옆 세로선</td><td>3×360</td><td>위아래 페이드, 그림 자체에 포함</td></tr></table>
<p class="note">그림만 검토하는 페이지입니다. 클릭·숫자는 강조만 바꾸며 전투 명령은 실행하지 않습니다. Game/ 연결·Unity 확인·실제 화면 캡처는 수행하지 않았습니다. 원본 PNG의 1화소를 기준으로 하며, 6° 회전과 1.45배 확대 때 도트가 고르게 보이는지는 실제 게임에서 확인해야 합니다.</p><footer>원안·제작 스크립트·규격·검사 결과: Docs/References/codex_k019_v1/</footer></main>
<script>const A=__ASSETS__;const $=s=>document.querySelector(s);let selected=-1;const words=['체력 낮은 적부터','체력 높은 적부터','가까운 적부터','오르는 적부터','특수 적 먼저','밀집한 곳 쏘기'];const roots=['명령하기 (이 성벽)','전령 부르기','소리 지르기'];$('#hero').src=A.hero;$('#rail').src=A.command_line;
function pick(i){selected=i;document.querySelectorAll('.choice').forEach((b,j)=>{b.classList.toggle('active',j===i);b.querySelector('.band').style.borderImageSource=`url("${A[j===i?'command_band_hover':'command_band_normal']}")`});$('#status').textContent=i<0?'선택 해제 · 보통 상태':`${i+1}번 · ${($('#mode').value==='six'?words:roots)[i]} · 마우스 올림 상태`;}
function render(){const list=$('#mode').value==='six'?words:roots;$('#scene').className='scene '+$('#bg').value+($('#mode').value==='three'?' three':'');$('#menu').replaceChildren();list.forEach((label,i)=>{const b=document.createElement('button');b.className='choice';b.style.top=`${i*58}px`;const k=list.length>1?(i-(list.length-1)/2)/((list.length-1)/2):0;b.style.left=`${46*(1-k*k)}px`;b.innerHTML=`<span class="band"></span><img class="badge" src="${A['command_number_'+(i+1)]}" alt="${i+1}번"><span class="label">${label}</span><img class="under" src="${A.command_underline}" alt="">`;b.onpointerenter=()=>pick(i);b.onfocus=()=>pick(i);b.onclick=()=>pick(i);$('#menu').append(b)});pick(-1)}$('#mode').onchange=render;$('#bg').onchange=render;$('#reset').onclick=()=>pick(-1);$('#scene').onpointerleave=()=>pick(-1);document.addEventListener('keydown',e=>{const n=Number(e.key);if(n>=1&&n<=$('.menu').children.length)pick(n-1);if(e.key==='Escape')pick(-1)});render();
const labels={command_band_normal:'보통 띠',command_band_hover:'마우스 올림 띠',command_underline:'금색 붓 밑줄',command_circle:'빈 번호 표식',command_line:'양끝 페이드 세로선'};for(const [key,src] of Object.entries(A)){if(key==='hero')continue;const d=document.createElement('div');d.className='tile';d.innerHTML=`<div>${labels[key]||key.replace('command_number_','번호 ')}</div><div class="check"><img src="${src}" alt="${labels[key]||'번호 표식'}" ${key==='command_line'?'style="height:180px;width:3px"':''}></div><code>${key}.png</code>`;$('#assets').append(d)}[280,380,520].forEach(w=>{const d=document.createElement('div');d.className='tile';d.innerHTML=`<div>${w}×48px</div><div class="slice" style='width:${w}px;height:48px;border-image-source:url("${A.command_band_normal}")'></div>`;$('#slices').append(d)});</script></html>'''
(ROOT/'_HTML/codex_K-019_commands_v1.html').write_text(page.replace('__ASSETS__',json.dumps(assets)),encoding='utf-8')
manifest=[]
for p in sorted((BASE/'png').glob('*.png')):
    raw=p.read_bytes()
    import struct
    w,h=struct.unpack('>II',raw[16:24])
    manifest.append(dict(file='png/'+p.name,width=w,height=h,sha256=hashlib.sha256(raw).hexdigest()))
(BASE/'manifest.json').write_text(json.dumps({'상태':'사용자 확정 전 시안','제작':'내장 imagegen 원안 + PowerShell 규격 추출','그림':manifest},ensure_ascii=False,indent=2),encoding='utf-8')
print('검토 HTML 및 목록 생성:',len(manifest),'개 그림')
